// Minimal hand-written stub of `node-cron`, enough for the TypeChecker to
// resolve the scheduler object from a fixture without a real install.
export interface ScheduledTask {
  stop(): void;
}

export interface NodeCron {
  schedule(expr: string, fn: () => void, options?: object): ScheduledTask;
}

declare const cron: NodeCron;
export default cron;
